import json, sys
path='$f'
types={}; sample_asst=None; sample_user=None
for line in open(path):
    try: o=json.loads(line)
    except: continue
    t=o.get('type'); types[t]=types.get(t,0)+1
    if t=='assistant' and not sample_asst:
        c=o.get('message',{}).get('content')
        if isinstance(c,list) and any(b.get('type')=='tool_use' and b.get('name') in ('Edit','Write') for b in c):
            sample_asst={k:str(v)[:60] for k,v in o.items() if k not in ('message',)}
    if t=='user' and not sample_user and not o.get('isMeta'):
        sample_user={k:str(v)[:60] for k,v in o.items() if k!='message'}
print(types)
print('ASST', sample_asst)
print('USER', sample_user)
"

